// 초등 교과서 기본 어휘 보강. WORD_BANK(wordbank.js) 뒤에 불러와 단계별 목록 끝에 붙인다.
// 행 형식: [단어, 발음기호, 뜻, 그림, 설명, [[예문, 해석] × 3]]
// id는 단어로 만들어서, 중간에 단어를 끼워 넣어도 다른 단어의 학습 기록이 바뀌지 않는다.
function addExtraWords(levelId, prefix, rows) {
  WORD_BANK[levelId].push(
    ...rows.map(([word, ipa, meaningKo, emoji, desc, examples]) => ({
      id: `${prefix}-${word.toLowerCase().replace(/[^a-z]+/g, "-")}`,
      word,
      ipa,
      meaningKo,
      emoji,
      desc,
      examples: examples.map(([en, ko]) => ({ en, ko })),
    }))
  );
}

